"""Time evolution under Hamiltonians (units with hbar = 1)."""

from __future__ import annotations

import torch


def time_evolution(hamiltonian: torch.Tensor, t: float | torch.Tensor) -> torch.Tensor:
    """Unitary generated by a time-independent Hamiltonian: U = exp(-i H t).

    Computed with ``torch.matrix_exp``, so gradients flow back to both the
    Hamiltonian (and any parameters it was built from) and the time.

    Args:
        hamiltonian: Hermitian matrix of shape ``(..., d, d)``. Hermiticity is
            not checked; a non-Hermitian input gives a non-unitary result.
        t: Evolution time, a float or a real tensor. Tensor times broadcast
            against the Hamiltonian's batch dimensions, e.g. ``t`` of shape
            ``(n,)`` with a single ``(d, d)`` Hamiltonian gives ``(n, d, d)``.

    Returns:
        Complex tensor of shape ``(..., d, d)``. Python-float times are treated
        as float64; the complex dtype is the promotion of the inputs.
    """
    if hamiltonian.ndim < 2 or hamiltonian.shape[-1] != hamiltonian.shape[-2]:
        raise ValueError(f"hamiltonian must have shape (..., d, d), got {tuple(hamiltonian.shape)}")

    if not isinstance(t, torch.Tensor):
        t = torch.tensor(t, dtype=torch.float64, device=hamiltonian.device)
    if t.is_complex():
        raise TypeError("t must be real")

    dtype = torch.promote_types(torch.promote_types(hamiltonian.dtype, t.dtype), torch.complex64)
    generator = -1j * t.to(dtype)[..., None, None] * hamiltonian.to(dtype)
    return torch.matrix_exp(generator)
